<template>
 <ElConfigProvider namespace="kel">
  <section class="jobs-native">
   <header><div><h1>{{ executionMode ? 'Executions' : '作业平台' }}</h1><p>{{ executionMode ? '执行记录与设备结果' : 'Flows' }}</p></div><div class="actions"><KsButton :loading="loading" @click="emit('refresh')">刷新</KsButton><KsButton v-if="!executionMode" :disabled="!canExecute" @click="emit('quickRun')">Quick Run</KsButton><KsButton v-if="!executionMode" type="primary" :disabled="!canCreate" @click="emit('create')">Create Flow</KsButton></div></header>
   <div v-if="executionMode" class="execution-views"><KsButton size="small" @click="emit('view','overview')">运行概况</KsButton><KsButton size="small" @click="emit('view','logs')">跨执行日志</KsButton><KsButton size="small" @click="emit('filter','state','FAILED')">失败记录</KsButton><KsButton size="small" @click="emit('filter','state','QUEUED')">排队记录</KsButton><KsButton size="small" @click="emit('filter','state','PAUSED')">暂停记录</KsButton></div><div v-if="error" class="error" role="alert">{{ error }}</div>
   <div v-if="selected.length" class="selection"><b>已选 {{selected.length}} 项</b><template v-if="!executionMode"><KsButton size="small" :disabled="!canEdit||loading" @click="emit('batch',selected,'enable')">启用所选</KsButton><KsButton size="small" :disabled="!canEdit||loading" @click="emit('batch',selected,'disable')">停用所选</KsButton></template><template v-else><KsButton v-for="a in [{id:'pause',label:'暂停所选'},{id:'resume',label:'继续所选'},{id:'kill',label:'终止所选'}]" :key="a.id" size="small" :disabled="!canExecute||loading" @click="emit('batch',selected,a.id)">{{a.label}}</KsButton></template><KsButton size="small" @click="selected=[]">清除选择</KsButton></div><KsDataTable :data="visible" :total="catalog?.total ?? filtered.length" :loading="loading" :currentPage="catalog?Math.floor(catalog.offset/catalog.limit)+1:page" :pageSize="catalog?.limit||size" :rowKey="'id'" :fitHeight="true" :loadData="loadPage" :selectable="executionMode?canExecute:!!canEdit" @selection-change="rows=>selected=rows" @sort-change="sort=>emit('sort',sort.prop||'name',sort.order==='descending'?'desc':'asc')" noDataText="暂无符合条件的记录" @row-click="row=>emit('open',row)">
    <template #navbar><div class="filters"><KsInput v-model="search" placeholder="搜索名称、ID、Namespace或来源" clearable @update:modelValue="page=1"/><label v-if="!executionMode" class="source-search"><input type="checkbox" :checked="sourceSearch" @change="emit('extraFilter','source_search',($event.target as HTMLInputElement).checked?'true':'')"/>源码搜索</label><select v-model="status" aria-label="状态筛选" @change="page=1"><option value="">全部状态</option><option v-for="s in statuses" :key="s">{{s}}</option></select><KsButton v-if="search||status" @click="search='';status='';page=1">清除筛选</KsButton><select v-if="!executionMode" :value="namespaceFilter||''" aria-label="Namespace筛选" @change="emit('extraFilter','namespace',($event.target as HTMLSelectElement).value)"><option value="">所有 Namespace</option><option v-for="n in catalog?.namespaces||[]" :key="n">{{n}}</option></select><select v-if="!executionMode" :value="targetFilter||''" aria-label="目标类型筛选" @change="emit('extraFilter','target_type',($event.target as HTMLSelectElement).value)"><option value="">所有目标类型</option><option value="server">Server</option><option value="switch">Switch</option><option value="both">Server & Switch</option></select><template v-if="executionMode"><select aria-label="执行来源" :value="executionFilters?.source||''" @change="emit('extraFilter','source',($event.target as HTMLSelectElement).value)"><option value="">所有来源</option><option v-for="source in ['flows','quick-run','schedule','backfill','replay','ztp','retry','restart']" :key="source">{{source}}</option></select><select aria-label="实际执行通道" :value="executionFilters?.transport||''" @change="emit('extraFilter','transport',($event.target as HTMLSelectElement).value)"><option value="">所有实际通道</option><option>AGENT</option><option>SSH</option></select><input type="datetime-local" aria-label="执行开始时间" :value="localTime(executionFilters?.since)" @change="emit('extraFilter','since',($event.target as HTMLInputElement).value)"/><input type="datetime-local" aria-label="执行结束时间" :value="localTime(executionFilters?.until)" @change="emit('extraFilter','until',($event.target as HTMLInputElement).value)"/></template><KsButton size="small" @click="emit('resetFilters')">清除筛选</KsButton><KsButton size="small" @click="columnsOpen=!columnsOpen">列</KsButton><div v-if="columnsOpen" class="columns"><template v-if="executionMode"><label><input type="checkbox" v-model="showSource"/>来源</label><label><input type="checkbox" v-model="showTransport"/>通道</label><label><input type="checkbox" v-model="showStarted"/>开始时间</label></template><template v-else><label><input type="checkbox" v-model="showDescription"/>描述</label><label><input type="checkbox" v-model="showRevision"/>Revision</label></template></div><span>{{ catalog?.total ?? filtered.length }} 条{{executionMode?'已加载执行':''}}</span></div></template>
    <KsTableColumn prop="name" :label="executionMode?'Execution / Flow':'Name / Flow ID'" :sortable="executionMode?false:'custom'" minWidth="250"><template #default="{row}"><button class="row-link" @click.stop="emit('open',row)">{{ executionMode?row.id.slice(0,12):row.name }}</button><small>{{executionMode?row.engine_flow_id:row.flow_id}}</small></template></KsTableColumn>
    <KsTableColumn v-if="!executionMode&&showDescription" prop="description" label="Description" minWidth="180"/>
    <KsTableColumn :prop="executionMode?'project_id':'namespace'" :label="executionMode?'Project':'Namespace'" minWidth="160"/>
    <KsTableColumn v-if="!executionMode" prop="target_type" label="Target" width="100"/>
    <KsTableColumn v-if="!executionMode&&showRevision" prop="revision" label="Revision" width="85"/>
    <KsTableColumn v-if="executionMode&&showSource" prop="source_module" label="Source" width="110"/>
    <KsTableColumn v-if="executionMode" label="Targets / Result" width="160"><template #default="{row}">{{row.targets.length}} targets<small>{{row.targets.filter(t=>t.state==='SUCCESS').length}} success / {{row.targets.filter(t=>t.state==='FAILED').length}} failed</small></template></KsTableColumn>
    <KsTableColumn v-if="executionMode&&showTransport" label="Mode / Transport" width="160"><template #default="{row}">{{row.mode}}<small>Agent {{row.targets.filter(t=>t.actual_transport==='AGENT').length}} / SSH {{row.targets.filter(t=>t.actual_transport==='SSH').length}}</small></template></KsTableColumn>
    <KsTableColumn v-if="executionMode&&showStarted" prop="created_at" label="Started" minWidth="160"><template #default="{row}">{{new Date(row.created_at).toLocaleString()}}</template></KsTableColumn>
    <KsTableColumn v-if="!executionMode" label="最近执行" minWidth="175"><template #default="{row}"><button v-if="row.recent_execution" class="row-link" @click.stop="emit('execution',row.recent_execution.id)"><KsExecutionStatus :status="row.recent_execution.state" size="small"/><small>{{new Date(row.recent_execution.created_at).toLocaleString()}}</small><small v-if="row.recent_execution.total">{{row.recent_execution.success}} / {{row.recent_execution.total}} 设备成功</small></button><span v-else>暂无执行</span></template></KsTableColumn><KsTableColumn label="State" width="145"><template #default="{row}"><KsExecutionStatus v-if="executionMode&&row.engine?.state?.current" :status="row.engine.state.current" size="small"/><span v-else>{{rowState(row)}}</span></template></KsTableColumn>
    <KsTableColumn v-if="!executionMode" label="Actions" width="150"><template #default="{row}"><KsButton size="small" :disabled="!canExecute||row.disabled||row.draft" @click.stop="emit('run',row)">Run</KsButton><KsButton size="small" @click.stop="emit('edit',row)">Edit</KsButton></template></KsTableColumn>
   </KsDataTable>
   <footer v-if="executionMode&&hasMore"><span>当前仅包含已加载记录</span><KsButton :loading="loading" @click="emit('loadMore')">加载更早执行</KsButton></footer>
  </section>
 </ElConfigProvider>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {ElConfigProvider} from 'element-plus';
import KsDataTable from '../../vendor/kestra/design-system/components/Data/KsDataTable/KsDataTable.vue';
import KsTableColumn from '../../vendor/kestra/design-system/components/Data/KsTable/KsTableColumn.vue';
import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';
import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';
import KsExecutionStatus from '../../vendor/kestra/design-system/components/Data/KsExecutionStatus/KsExecutionStatus.vue';
const props=defineProps<{executionFilters?:Record<string,string>;catalog?:any;sourceSearch?:boolean;canEdit?:boolean;namespaceFilter?:string;targetFilter?:string;rows:any[];executionMode:boolean;loading:boolean;error:string;canCreate:boolean;canExecute:boolean;hasMore:boolean;query:string;stateFilter:string}>();
const emit=defineEmits(['refresh','quickRun','create','open','run','edit','loadMore','filter','page','batch','extraFilter','execution','view','sort','resetFilters']);
const page=ref(1),size=ref(25),selected=ref<any[]>([]),columnsOpen=ref(false),showDescription=ref(true),showRevision=ref(true),showSource=ref(true),showTransport=ref(true),showStarted=ref(true);
const localTime=(v?:string)=>{if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const search=computed({get:()=>props.query,set:value=>emit('filter','q',value)});
const status=computed({get:()=>props.stateFilter,set:value=>emit('filter','state',value)});
const rowState=(row:any)=>props.executionMode?row.engine?.state?.current||row.error_code||'unknown':!row.engine||!Object.keys(row.engine).length?'unknown':row.draft?'DRAFT':row.disabled?'DISABLED':'ENABLED';
const statuses=computed(()=>props.executionMode?[...new Set(props.rows.map(rowState))]:['ENABLED','DRAFT','DISABLED','unknown']);
const filtered=computed(()=>props.catalog?props.rows:props.rows.filter(r=>(!status.value||rowState(r)===status.value)&&JSON.stringify([r.id,r.name,r.namespace,r.flow_id,r.engine_flow_id,r.source_module]).toLowerCase().includes(search.value.toLowerCase())));
const visible=computed(()=>props.catalog?props.rows:filtered.value.slice((page.value-1)*size.value,page.value*size.value));
function loadPage(p:{page:number;size:number}){if(props.catalog)emit('page',p.page,p.size);else{page.value=p.page;size.value=p.size}}
watch(()=>[props.executionMode,props.query,props.stateFilter,props.namespaceFilter,props.targetFilter],()=>{page.value=1;selected.value=[]});watch(()=>props.rows,()=>selected.value=[]);
</script>
<style scoped>
.jobs-native{display:flex;flex-direction:column;min-height:650px;height:calc(100vh - 120px);color:var(--ks-text-primary);font-family:var(--ks-font-family-sans);font-size:var(--ks-font-size-base);background:var(--ks-bg-surface)}
header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--ks-border-default)}h1{font-size:24px;line-height:1.4;margin:0;font-weight:600}p{margin:3px 0 0;color:var(--ks-text-secondary);font-size:12px}.actions,.filters{display:flex;align-items:center;gap:8px}.source-search{font-size:11px;white-space:nowrap;display:flex;align-items:center;gap:5px}.filters{padding:12px 16px;flex-wrap:wrap;position:relative}.execution-views{display:flex;gap:8px;padding:10px 16px;border-bottom:1px solid var(--ks-border-default)}.selection{display:flex;align-items:center;gap:8px;padding:8px 16px;border-bottom:1px solid var(--ks-border-default);font-size:12px}.columns{position:absolute;right:12px;top:50px;z-index:10;padding:12px;background:var(--ks-bg-elevated);border:1px solid var(--ks-border-default);display:grid;gap:8px}.filters>.kel-input{max-width:360px}.filters>span{margin-left:auto;font-size:12px;color:var(--ks-text-secondary)}select{background:var(--ks-bg-input);border:1px solid var(--ks-border-default);border-radius:4px;padding:7px;color:inherit}small{display:block;color:var(--ks-text-secondary);font-size:11px;margin-top:4px}.row-link{font:inherit;font-weight:600;border:0;background:none;cursor:pointer;color:var(--ks-text-link)}.ks-data-table-wrapper{flex:1;min-height:0}.error{padding:12px;color:#d34359}footer{display:flex;align-items:center;justify-content:flex-end;gap:12px;padding:12px;font-size:12px}
.filters>input[type=datetime-local]{font-size:10px;max-width:170px;padding:6px;background:var(--ks-bg-input);color:var(--ks-text-primary);border:1px solid var(--ks-border-default);border-radius:4px}</style>
